<?php

namespace Database\Seeders;

use App\Models\HR\DocumentTemplate;
use Illuminate\Database\Seeder;

/**
 * DOCS/Гэрээ фолдэрт байгаа албан ёсны маягтуудыг систем дэх загвар болгон
 * бүртгэнэ. Ажилтан тус бүрийн мэдээлэл {{талбар}} хэлбэрээр орлуулагдана.
 *
 * Гарын үсгийн блокыг загварт бичээгүй — системээс хоёр талын цахим
 * гарын үсгийг PDF дээр автоматаар зурдаг тул давхардуулах шаардлагагүй.
 */
class HrDocumentTemplateSeeder extends Seeder
{
    public function run(): void
    {
        $templates = [
            [
                'code' => 'hr-employment',
                'type' => 'employment',
                'title' => 'Хөдөлмөрийн гэрээ',
                'description' => 'Монгол Улсын Хөдөлмөрийн тухай хуулийг үндэслэсэн үндсэн хөдөлмөрийн гэрээ.',
                'sort_order' => 1,
                'body' => $this->employmentBody(),
            ],
            [
                'code' => 'hr-liability',
                'type' => 'liability',
                'title' => 'Эд хөрөнгийн бүрэн хариуцлагын гэрээ',
                'description' => 'Хөдөлмөрийн гэрээний хавсралт — компанийн эд хөрөнгийн бүрэн бүтэн байдлыг хангах гэрээ.',
                'sort_order' => 2,
                'body' => $this->liabilityBody(),
            ],
            [
                'code' => 'hr-nda',
                'type' => 'nda',
                'title' => 'Нууц хадгалах гэрээ',
                'description' => 'Хөдөлмөрийн гэрээний хавсралт — байгууллагын болон үйлчлүүлэгчийн нууцыг хадгалах гэрээ.',
                'sort_order' => 3,
                'body' => $this->ndaBody(),
            ],
            [
                'code' => 'hr-jd-reception',
                'type' => 'job_description',
                'title' => 'Угтах үйлчилгээний ажилтны ажлын байрны тодорхойлолт',
                'description' => 'Ресепшний ажилтны ажлын байрны тодорхойлолт. Бусад албан тушаалд хуулбарлаж засварлана.',
                'sort_order' => 4,
                'body' => $this->receptionJobDescriptionBody(),
            ],
        ];

        $defaults = [
            'requires_employer_signature' => true,
            'requires_employee_signature' => true,
            'is_active' => true,
        ];

        foreach ($templates as $template) {
            $existing = DocumentTemplate::withTrashed()->where('code', $template['code'])->first();

            if (! $existing) {
                DocumentTemplate::create($template + $defaults);

                continue;
            }

            // HR загварыг системээс засварладаг тул гараар оруулсан
            // өөрчлөлтийг дарж бичихгүй — хөндөөгүй загварыг л шинэчилнэ.
            if ($existing->updated_at->equalTo($existing->created_at)) {
                $existing->update($template);
            }
        }
    }

    private function employmentBody(): string
    {
        return <<<'HTML'
<table class="plain">
<tr>
<td style="width:34%">{{doc_year}} оны ____ дугаар<br />сарын _____-ны өдөр</td>
<td style="width:33%;text-align:center">Дугаар {{doc_number}}</td>
<td style="width:33%;text-align:right">{{city}}</td>
</tr>
</table>

<p class="ctr">Монгол Улсын Хөдөлмөрийн тухай хуулийг үндэслэн:</p>

<table class="plain">
<tr>
<td style="width:26%"><strong>НЭГ ТАЛААС:</strong></td>
<td style="width:74%">{{company_name}} /цаашид “Ажил олгогч” гэнэ/-ийг төлөөлж {{director_position}} {{director_name}}</td>
</tr>
<tr>
<td><strong>НӨГӨӨ ТАЛААС:</strong></td>
<td>{{employee_address}} хаягт оршин суух, РД: {{employee_register}} тоот регистерийн дугаартай иргэн {{employee_last_name}} овогтой {{employee_first_name}} /цаашид “Ажилтан” гэнэ/ нар /цаашид хамтад нь “Талууд” гэнэ/</td>
</tr>
</table>

<p>ажил олгогчоос тогтоосон Хөдөлмөрийн дотоод журам болон эрүүл мэндийн байгууллагад хамааралтай холбогдох бусад дүрэм, журам, заавар, стандартыг Ажилтан дагаж мөрдөхөөр харилцан тохиролцож, дор дурдсан нөхцөлөөр ЭНЭХҮҮ ГЭРЭЭГ байгуулав.</p>
<p>Уг гэрээгээр Ажил олгогч болон Ажилтны хооронд үүсэх хөдөлмөрийн харилцааг зохицуулна.</p>

<h2>Нэг. Хөдөлмөрийн гэрээний гол нөхцөл</h2>
<p class="cl">1.1. Ажилтны ажиллах хэлтэс, нэгж: {{branch}}</p>
<p class="cl">1.2. Ажилтны эрхлэх ажил, албан тушаалын нэр: {{position}}</p>
<p class="cl">1.3. Ажилтны гүйцэтгэх ажил, үүргүүд: Ажлын байрны тодорхойлолтын дагуу</p>
<p class="cl">1.4. Ажилтны сарын үндсэн цалин: {{salary}} /{{salary_text}}/</p>
<p class="cl">Үндсэн цалинг сард 2 удаа хувааж олгох ба хуулийн дагуу татвар, нийгмийн болон эрүүл мэндийн даатгалын шимтгэлийг суутгана.</p>
<p class="cl">1.5. Хөдөлмөрийн нөхцөл: {{work_condition}}</p>
<p class="cl">1.6. Хөдөлмөрийн гэрээний хугацаа: {{contract_term}}</p>
<p class="cl">1.7. Эмнэлгийн мэргэжилтний ёс зүйн дүрмийн дагуу өвчтөн-үйлчлүүлэгчид үзүүлж эхэлсэн эмчилгээ үйлчилгээг бүрэн дуусах хүртэл хугацаанд энэхүү гэрээ хүчин төгөлдөр байх бөгөөд аль нэг талын санаачлагаар цуцлахгүй болно.</p>

<h2>Хоёр. Ажил, амралтын цаг болон нэмэгдэл цалин,<br />шагнал, урамшуулал</h2>
<p class="cl">2.1. Ердийн ажлын өдрүүдэд ажлын цагийн үргэлжлэх хугацаа 8 цаг, 7 хоногт нийт 40 цаг байна. /Ээлжийн зохион байгуулалттай ажилтнуудад хамаарахгүй./</p>
<p class="cl">2.2. Ажил үүргийн онцлог болон Ажил олгогчоос даалгасан ажлын шаардлагын дагуу ердийн өдрийн ажлын цагийг сунгаж, ажилтан нь илүү цагаар ажиллана. Илүү цагаар ажилласан ажилтныг нөхөн амруулна, эсхүл зохих журмын дагуу илүү цагийн хөлс олгож болно.</p>
<p class="cl">2.3. Ажлын шаардлагаар амралтын өдөр, шөнийн цаг, нийтээр амрах баярын өдөр ажилласан ажилтныг Ажил олгогчийн зөвшөөрлийн дагуу биеэр нөхөн амруулна. /Ээлжийн зохион байгуулалтад орж ажиллаж байгаа ажилтнуудад энэ заалт хамаарахгүй./</p>
<p class="cl">2.4. Ажилтанд ажлын гүйцэтгэл, үр дүнгээр олгох нэмэгдэл цалин, шагнал, урамшуулал болон бусад нэмэгдлийг Ажил олгогчоос баталсан холбогдох журмын дагуу тооцож олгоно. Тэтгэмж, буцалтгүй тусламж, хөнгөлөлтийг Хөдөлмөрийн дотоод журамд заасан нөхцөл, болзол, хувь хэмжээгээр олгоно.</p>
<p class="cl">2.5. Ажилтан нь ажлын шаардлагаар ажил, үүрэг хавсран гүйцэтгэх бол Хөдөлмөрийн тухай хуулийг үндэслэн түүнд ажил хавсран гүйцэтгэсний нэмэлт хөлсийг ажил хавсран гүйцэтгэсэн хугацаагаар хавсран гүйцэтгэж буй ажлын үндсэн цалингийн 40 хүртэл хувиар тооцон олгож болно.</p>

<h2>Гурав. Талуудын эрх, үүрэг</h2>
<h3>3.1. Ажил олгогч дараах эрхтэй:</h3>
<p class="cl">3.1.1. Хөдөлмөрийн тухай хууль, Эрүүл мэндийн тухай хууль, Эмнэлгийн тусламж үйлчилгээний тухай хууль, Эмнэлгийн мэргэжилтний ёс зүйн хэм хэмжээ, Хөдөлмөрийн дотоод журам болон эмнэлгийн байгууллагад хамааралтай холбогдох бусад дүрэм, журам, зааврыг сахин биелүүлж, хөдөлмөрийн гэрээ, ажлын байрны тодорхойлолтоор хүлээсэн чиг үүргээ үнэнч шударгаар биелүүлэхийг ажилтнаас шаардах, холбогдох эрх зүйн актуудыг сахин мөрдүүлэх арга хэмжээ авах;</p>
<p class="cl">3.1.2. Амжилт бүтээл гаргасан, үнэнч шударга ажилласан, өмч хөрөнгө хамгаалсан, өртөг зардал хямдруулж, ашиг орлого нэмэгдүүлсэн, шинэ техник, технологи дэвшилтэд арга барил эзэмшсэн ажилтныг шагнаж урамшуулах, төр засгийн болон бусад байгууллагын шагналд тодорхойлох;</p>
<p class="cl">3.1.3. Хөдөлмөрийн тухай хууль, Хөдөлмөрийн дотоод журам болон Хөдөлмөрийн гэрээ, Нууц хадгалах гэрээ, Эд хөрөнгийн бүрэн хариуцлагын гэрээнд заасан үндэслэлээр ажилтанд хөдөлмөрийн сахилгын шийтгэл ногдуулах, эд хөрөнгийн хариуцлага хүлээлгэх;</p>
<p class="cl">3.1.4. Хөдөлмөрийн тухай хуулийн дагуу ажилтныг компани дотроо өөр ажилд шилжүүлэх, түр шилжүүлэх, хөдөлмөрийн гэрээг цуцлах, дуусгавар болгох;</p>
<p class="cl">3.1.5. Ажилтны буруутай үйлдэл, эс үйлдлээс болж компанид хохирол учирсан тохиолдолд зохих төлбөрийг төлүүлэх, хариуцлага хүлээлгүүлэхээр хууль, шүүхийн байгууллагад нэхэмжлэл гаргах;</p>
<p class="cl">3.1.6. Ажилтны мэдлэг, мэргэжил, ур чадварыг дээшлүүлэх зорилгоор сургалт зохион байгуулах, мэргэжлийн чадварыг шалгах, түвшин тогтоох аттестатчлал явуулах, түүний үр дүнг үндэслэн албан тушаал дэвшүүлэх, бууруулах;</p>
<p class="cl">3.1.7. Компанийн зардлаар дотоод, гадаадад сургалтад хамрагдсан ажилтныг сургалтын гэрээний дагуу тогтвор суурьшилтай ажиллахыг шаардах, хэрэв ажилтан өөрийн санаачилгаар Хөдөлмөрийн гэрээгээ цуцалсан тохиолдолд сургалтын төлбөр, холбогдох бусад зардлыг нөхөн төлөхийг шаардах;</p>
<p class="cl">3.1.8. Хөдөлмөрийн гэрээ цуцлагдах нөхцөл байдал бий болсон үед ажилтан ажлаа зохих ёсоор хүлээлцээгүй бол цалин хөлсийг олгохгүй байх.</p>

<h3>3.2. Ажил олгогч дараах үүрэгтэй:</h3>
<p class="cl">3.2.1. Компанийн зорилго, бодлого, удирдлага, үйл ажиллагааны зарчим, стратеги зорилтыг үндэслэн ажлын байрны тодорхойлолтыг оновчтой гаргах, ажилтныг мэргэжил, мэргэшлийг харгалзан ажиллуулах;</p>
<p class="cl">3.2.2. Хөдөлмөрийн тухай хууль, Хөдөлмөрийн дотоод журамд заасны дагуу ажилтан бүртэй Хөдөлмөрийн гэрээг бичгээр байгуулах;</p>
<p class="cl">3.2.3. Ажилтныг нийгмийн болон эрүүл мэндийн даатгалд заавал даатгуулж, хуульд заасан хувь хэмжээгээр сар бүр нийгмийн даатгалын шимтгэл төлөх, хөдөлмөрийн гэрээ байгуулсан өдрөөс эхлэн ажилтанд нийгмийн болон эрүүл мэндийн даатгалын дэвтэр нээж, түүнд зохих журмын дагуу сар тутам шимтгэл хураамж төлсөн тухай бичилт хийх;</p>
<p class="cl">3.2.4. Хөдөлмөрийн аюулгүй байдал, эрүүл ахуйн тухай хууль тогтоомжид заасны дагуу ажилтны ажил, үүргээ гүйцэтгэхэд шаардагдах ажлын байрны орчин нөхцөлийг бүрдүүлж, шаардлагатай ажлын хувцас, багаж, тусгай хэрэгслээр хангах;</p>
<p class="cl">3.2.5. Ажилтны ажлын гүйцэтгэлийг үнэлж дүгнэн үр дүнд нь тохирсон цалин хөлс олгох, ажилтны шинэ санаа, санаачилгыг дэмжиж ажиллах;</p>
<p class="cl">3.2.6. Ажилтнуудын дунд ажил хэрэгч, хамтач, бүтээлч уур амьсгалыг бий болгох, идэвхи санаачилгыг бүх талаар өрнүүлэх, ажилтнаас тавьсан санал, хүсэлтийг хүлээн авч хэлэлцэн шийдвэрлэж, авсан арга хэмжээний талаар хариу мэдээллэж байх;</p>
<p class="cl">3.2.7. Компанийн санхүүгийн чадварыг харгалзан үзэж ажилтны мэргэжил, мэдлэгээ дээшлүүлэх, нийгмийн асуудлыг шийдвэрлэхэд чиглэсэн сургалт, хүний нөөцийн бодлого боловсруулан хэрэгжүүлэх;</p>
<p class="cl">3.2.8. Үйлдвэрлэлийн осол, хурц хордлого, мэргэжлээс шалтгаалах өвчнөөс урьдчилан сэргийлэх зорилгоор нийт ажилтнуудыг жил бүр эмнэлгийн үзлэг, шинжилгээнд хамруулах, хөдөлмөрийн хэвийн бус нөхцөлд ажилладаг ажилтанд хамгаалах хэрэгсэл, ажлын тусгай хувцас, хор саармагжуулах бодис, хоол, хүнсний бүтээгдэхүүн олгох;</p>
<p class="cl">3.2.9. Ажилтныг ажил үүргээ гүйцэтгэхэд нь зайлшгүй шаардлагатай мэдээлэл /ном, товхимол, сонин сэтгүүл, гарын авлага, интернет сүлжээ г.м/-ээр хангах.</p>

<h3>3.3. Ажилтан дараах эрхтэй:</h3>
<p class="cl">3.3.1. Хөдөлмөрийн аюулгүй байдал, эрүүл ахуйн шаардлагад нийцсэн хөдөлмөрийн нөхцөлөөр хангуулах, ажлынхаа үр дүнд тохирсон цалин хөлс авах;</p>
<p class="cl">3.3.2. Хөдөлмөрийн дотоод журамд заасан хөнгөлөлт, тэтгэмж, буцалтгүй тусламж авах хүсэлт гаргах;</p>
<p class="cl">3.3.3. Хөдөлмөрийн тухай хууль тогтоомжид заасны дагуу амрах, тэтгэвэр, тэтгэмж авах, бусад хөнгөлөлт эдлэх;</p>
<p class="cl">3.3.4. Үндэслэлгүйгээр халагдсан, сахилгын шийтгэл буруу ногдуулсан гэж үзвэл гомдол гаргах;</p>
<p class="cl">3.3.5. Хөдөлмөрийн тухай хууль, Хөдөлмөрийн дотоод журамд заасны дагуу амрах, жилд нэг удаа ээлжийн амралт эдлэх, чөлөө олгохыг хүсэх;</p>
<p class="cl">3.3.6. Компанийн ашиг, орлогыг нэмэгдүүлэх, ажил сайжруулах, дутагдлыг арилгах, зардал бууруулах зэрэгтэй холбогдсон санал, хүсэлтийг амаар болон бичгээр Ажил олгогчид танилцуулах, хариу авах;</p>
<p class="cl">3.3.7. Компанийн сургалтын бодлого, журмын хүрээнд мэдлэг, мэргэжлээ дээшлүүлэхээр дотоод, гадаадын сургалтад компанийн болон өөрийн зардлаар хамрагдах;</p>
<p class="cl">3.3.8. Хөдөлмөрийн тухай хуульд заасны дагуу өөрийн санаачилгаар хөдөлмөрийн гэрээг цуцлах, дуусгавар болгох.</p>

<h3>3.4. Ажилтан дараах үүрэгтэй:</h3>
<p class="cl">3.4.1. Хөдөлмөрийн тухай хууль, Эрүүл мэндийн тухай хууль, Эмнэлгийн тусламж үйлчилгээний тухай хууль, Эмнэлгийн мэргэжилтний ёс зүйн хэм хэмжээ, Хөдөлмөрийн дотоод журам болон эмнэлгийн байгууллагад хамааралтай холбогдох бусад дүрэм, журам, зааврыг сахин биелүүлж хөдөлмөрийн гэрээ, ажлын байрны тодорхойлолтоор гүйцэтгэх чиг үүрэг болон удирдлагаас өгсөн үүрэг, даалгаврыг цаг тухайд нь биелүүлэх, компанид мөрдөж буй дүрэм, журам, заавартай танилцаж өдөр тутмын үйл ажиллагаандаа мөрдөж ажиллах, ажлын гүйцэтгэлээ тайлагнах;</p>
<p class="cl">3.4.2. Холбогдох хууль тогтоомжид заасан хувь хэмжээгээр нийгмийн болон эрүүл мэндийн даатгалын шимтгэл, хураамж, татвар төлөх;</p>
<p class="cl">3.4.3. Өвчтөн-үйлчлүүлэгчдэд өөрийн эрх хэмжээний хүрээнд зөвлөгөө өгөх, эмнэлгийн дүрэм, журам, үйлчилгээний стандартын дагуу тэдгээртэй харилцаж зохих мэдээллийг түргэн шуурхай, бүрэн дүүрэн өгч байх;</p>
<p class="cl">3.4.4. Ажил олгогчоос тогтоосон эмчилгээ, үйлчилгээний нормативийг хангаж ажиллах;</p>
<p class="cl">3.4.5. Эмч, эмнэлгийн ажилтны ёс зүйн хэм хэмжээг чанд сахиж, сахилга, ёс зүйн зөрчил гаргахгүй байх, өвчтөн-үйлчлүүлэгчидтэй зөв боловсон харьцах;</p>
<p class="cl">3.4.6. Компанийн бизнесийн үйл ажиллагаатай холбогдсон компанийн болон харилцагч, өвчтөн-үйлчлүүлэгчийн талаарх мэдээллийг нууцлах, нууцыг чандлан хадгалах, хамгаалах, бусдад мэдээлэл өгөхгүй байх, шаардлагатай тохиолдолд зөвхөн Захирлын зөвшөөрлөөр хэвлэл мэдээллийн хэрэгсэл, гуравдагч этгээдэд мэдээлэл өгөх;</p>
<p class="cl">3.4.7. Ажлын цагийг зөвхөн ажил үүргээ гүйцэтгэхэд зориулах бөгөөд гадуур ажлаар явахдаа Захиралд мэдэгдэх ба хүндэтгэн үзэх шалтгаанаар албан үүргээ гүйцэтгэх боломжгүй тохиолдолд урьдчилан мэдэгдэж холбогдох журмын дагуу чөлөө авах;</p>
<p class="cl">3.4.8. Өвчтөн-үйлчлүүлэгчидтэй эелдэг боловсон харилцах, ажил үүргээ гүйцэтгэхдээ танил тал харах, шан харамж шаардах зэргээр компанийн ажилтны нэр хүнд, ёс зүйд харшлах аливаа үйлдэл гаргахгүй байх, албаны үйл ажиллагаанд удирдах удирдуулах ёс журмыг эрхэмлэх;</p>
<p class="cl">3.4.9. Компанийн эд хогшил, өөрийн эзэмшилд байгаа эд зүйлийн бүрэн бүтэн байдлыг хадгалж, эд материалыг ариг гамтай, зориулалтын дагуу зүй зохистой ашиглах, компанийн эд хөрөнгөд өөрийн буруугаас хохирол учруулсан тохиолдолд нөхөн төлөх;</p>
<p class="cl">3.4.10. Ажилтан өөрийн хариуцсан ажлын талаарх бичиг хэргийг эмх цэгцтэй, цэвэр нямбай хөтөлж, цаашид тогтмол ашиглахгүй баримт материалуудаа үдэж цэгцлэн архивлан хадгалах;</p>
<p class="cl">3.4.11. Ажилтан ажлын шаардлагаар гар утсаа байнга нээлттэй байлгаж, гэрийн хаяг, утасны дугаарт өөрчлөлт орсон тохиолдолд тухай бүр нь Ажил олгогчид мэдэгдэж өөрчлөлт оруулж байх;</p>
<p class="cl">3.4.12. Хөдөлмөрийн аюулгүй ажиллагаа, эрүүл ахуйн шаардлагуудыг чанд сахин биелүүлж, хариуцаж буй эм бэлдмэл, бодис болон техник, тоног төхөөрөмжийн ашиглалтын зааврыг чанд мөрдөн болзошгүй аюул эрсдлээс урьдчилан сэргийлэх;</p>
<p class="cl">3.4.13. Ажлын цаг бүртгэлийн журмын дагуу хурууны хээг тогтоосон цагт заавал уншуулах, ажлын цагийг үр дүнтэй өнгөрүүлж, хамт олны дунд ажил хэрэгч, нөхөрсөг эвсэг харьцааг эрхэмлэх;</p>
<p class="cl">3.4.14. Хариуцсан ажил үүргээ Захирал зөвшөөрснөөс бусад тохиолдолд өөр хүнээр гүйцэтгүүлэхгүй байх;</p>
<p class="cl">3.4.15. Ажилтан компанид тогтвор суурьшилтай ажиллах үүрэгтэй бөгөөд өөрийн хүсэлтээр, эсхүл сахилгын шийтгэлээр ажлаас халагдсан, чөлөөлөгдсөн тохиолдолд компанийн зардлаар хамрагдсан аливаа сургалтын зардлыг үл маргах журмаар компанид буцаан нөхөн төлөх;</p>
<p class="cl">3.4.16. Энэхүү гэрээ болон хөдөлмөрийн дотоод журам, эмнэлгийн байгууллагад хамааралтай холбогдох бусад дүрэм, журам, заавар, эрх зүйн актаар хүлээсэн үүргээ биелүүлээгүй буюу зөрчсөн бусад ажилтны үйлдэл, эс үйлдэхүйтэй үл эвлэрч, мэдсэн нэн даруйдаа Захирал, Хуулийн зөвлөхөд яаралтай мэдэгдэх, зөрчлийг таслан зогсоох шаардлага тавих.</p>

<h2>Дөрөв. Талуудын хүлээх хариуцлага</h2>
<p class="cl">4.1. Ажилтан нь Хөдөлмөрийн дотоод журам, Эмч, эмнэлгийн ажилтны ёс зүйн дүрэм, Ажлын байрны тодорхойлолт, хөдөлмөрийн гэрээгээр хүлээсэн үүргээ биелүүлээгүй бол Хөдөлмөрийн тухай хууль болон энэхүү журамд заасны дагуу хариуцлага хүлээнэ.</p>
<p class="cl">4.2. Энэхүү гэрээг байгуулах нь ажилтны эрх зүйн чадвар, чадамжийг хязгаарласан аливаа зүйл байхгүй гэдгийг баталж байгаа явдал бөгөөд хэрэв Ажилтан энэ гэрээг байгуулснаар хэн нэгэн гуравдагч этгээдийн эрх ашгийг хөндсөн бол тэрээр энэхүү зөрчлөөс үүсэх аливаа хариуцлагыг өөрөө бүрэн хариуцна.</p>
<p class="cl">4.3. Хэрэв гэрээний аль нэг тал нь үүргээ биелүүлэхэд давагдашгүй хүчин зүйл нөлөөлсөн гэдгийг баталсан, эсхүл үүргээ биелүүлэх талаар боломжтой буюу шаардлагатай бүх арга хэмжээг авснаа нотолсон бол сахилгын хариуцлагаас чөлөөлөгдөж болно.</p>

<h2>Тав. Хөдөлмөрийн гэрээг дуусгавар болгох, цуцлах</h2>
<p class="cl">5.1. Талууд энэхүү гэрээг Хөдөлмөрийн тухай хуульд заасан үндэслэл, журмаар цуцалж, дуусгавар болгоно. Ажилтан хөдөлмөрийн гэрээ цуцлах өргөдлөө Ажил олгогчид өгснөөс хойш 30 хоног өнгөрмөгц ажлын байраа орхих эрхтэй. Энэ хугацаанд эд хөрөнгийн болон бусад тооцоогоо дуусгавар болгож тойрох хуудсаа бөглүүлэн компанийн Хуулийн зөвлөхөд хүлээлгэн өгч тушаал шийдвэрийн хувийг авна.</p>
<p class="cl">5.2. Хүндэтгэн үзэх шалтгаантай, эсхүл ажлаас чөлөөлөх хугацааг Ажил олгогчтой харилцан тохиролцсон бол хөдөлмөрийн гэрээг 5.1-д заасан 30 хоногоос өмнө цуцална.</p>
<p class="cl">5.3. Дараах зөрчлийг ноцтой зөрчилд тооцох бөгөөд энэ нь хөдөлмөрийн гэрээг шууд цуцлах үндэслэл болно. Үүнд:</p>
<p class="cl">5.3.1. Ажлын цагаар ажлын байранд болон албан томилолтоор ажил үүргээ гүйцэтгэж байх үедээ согтууруулах ундаа, мансууруулах эм, сэтгэцэд нөлөөт бодис хэрэглэсэн, бусдад өгсөн, худалдсан, хэрэглэсэн үедээ ажлын байранд нэвтэрсэн, нэвтрэхийг оролдож компанийн хэвийн үйл ажиллагааг алдагдуулсан;</p>
<p class="cl">5.3.2. Захирал, Ерөнхий эмчээс өгсөн үүрэг даалгавар, хөдөлмөрийн гэрээ, ажлын байрны тодорхойлолтод тусгагдсан ажлыг удаа дараа /2 буюу түүнээс дээш/ зохих ёсоор биелүүлээгүй, ажил үүрэгтэй нь холбогдуулан тавьсан удирдлагын шаардлагыг эсэргүүцсэн;</p>
<p class="cl">5.3.3. Хүндэтгэн үзэх шалтгаангүй, ажил олгогчид урьдчилан мэдэгдэлгүйгээр ажлын 2 өдөр ба түүнээс дээш өдөр ажил тасалсан, эсхүл ажилтан өвчний улмаас хөдөлмөрийн чадвар түр алдсан болон хүндэтгэн үзэх бусад шалтгаанаар ажилдаа ирээгүй тохиолдолд холбогдох баримт бичгийг ажилдаа ирснээс хойш ажлын 2 өдөрт багтаан Ажил олгогчид өгөөгүй, дур мэдэн ажлын байраа орхин явсан;</p>
<p class="cl">5.3.4. Ажилд орох материалыг хуурамчаар бүрдүүлсэн, эмнэлгийн хуудас болон бусад баримт бичгийг хуурамчаар үйлдсэн, бүрдүүлсэн, ашигласан, засварласан;</p>
<p class="cl">5.3.5. Хөдөлмөрийн тухай хуульд заасан үндэслэлээр ажил, албан тушаал нь хэвээр хадгалагдаж байгаа ажилтан тухайн шалтгаан нөхцөл арилсан болон хугацаа дууссанаас хойш ажлын 2 ба түүнээс дээш өдөр ажилдаа ирээгүй;</p>
<p class="cl">5.3.6. Санхүү, нягтлан бодох бүртгэлийн данс бүртгэл будлиантуулсан, компанийн мөнгөн хөрөнгийн бүрэн бүтэн байдлыг алдагдуулсан, эсхүл тийм нөхцөл боломжийг бий болгосон, түүнд халдах оролдлого гаргасан, түүнд нь тусалсан, мөн төлбөр тооцооны баримтад компанийг төлөөлж гарын үсэг зурсан, гүйлгээ хийсэн /Энэ тохиолдолд хууль, хяналтын байгууллагад шилжүүлнэ./;</p>
<p class="cl">5.3.7. Ажил, албан тушаалаа урвуулан ашигласан, эрх мэдлээ хэтрүүлсэн, эрхэлсэн ажил, албан тушаалын онцлогоо хувийн зорилгоор ашигласан /бусдаас шан харамж авсан, хувьдаа үйлчилгээ хийлгэсэн, байгууллагын өмч хөрөнгийг хувьдаа ашиглаж завшсан, бусдад зориуд ашиглуулсан, байгууллагын зардлаар хувийн хэрэгцээгээ хангасан, бизнесээ дэмжсэн, тийм боломжийг бий болгосон гэх зэрэг/;</p>
<p class="cl">5.3.8. Ажил үүргээ гүйцэтгэх явцдаа олж мэдсэн мэдээ мэдээлэл, байгууллага, хувь хүний нууцтай холбоотой баримтыг бусдад задруулсан, дамжуулсан, байгууллагын хэвлэмэл хуудас /албан бланк/, тамга, тэмдгийг хувийн зорилгоор ашигласан, бусдад ашиглуулсан, ашиглах нөхцөл бололцоог бүрдүүлсэн, компанийн нэрийг ашиглан өөр бусад байгууллага, иргэдийг хуурч мэхэлсэн /Энэ тохиолдолд хууль, хяналтын байгууллагад шилжүүлнэ./;</p>
<p class="cl">5.3.9. Компанийн бизнесийн нэр хүндийг гутаасан, бизнесийн үйл ажиллагаанд сөрөг нөлөө үзүүлэхүйц оролдлого хийж худал мэдээлэл бусдад тараасан, компанийн эсрэг үйл ажиллагаа явуулсан, Захирлын зөвшөөрөлгүйгээр хэвлэл мэдээллийн хэрэгслээр компанийн нууцтай болон өөрийн албан ажилтай холбоотой мэдээ, мэдээллийг тараасан, нийтлүүлсэн, ярилцлага өгсөн, интернэт, цахим орчинд үзэл бодлоо илэрхийлэхдээ компанийн нэр хүндэд халдсан худал мэдээлэл тараасан зэрэг нь баримтаар нотлогдсон /Энэ тохиолдолд хууль, хяналтын байгууллагад шилжүүлнэ./;</p>
<p class="cl">5.3.10. Ажил мэргэжлийн дагуу тусгайлан тогтоосон ёс зүйн хэм хэмжээ, дүрэм, журмыг зөрчсөн, эмч, мэргэжилтэн, ажилтнууд хоорондоо болон өвчтөн-үйлчлүүлэгчтэй харилцахдаа ёс зүйн хэм хэмжээг зөрчсөн /Энэ тохиолдолд эмч, эмнэлгийн мэргэжилтний ёс зүйн хэм хэмжээ хариуцсан төрийн эрх бүхий байгууллагад шилжүүлнэ./;</p>
<p class="cl">5.3.11. Захирлын зөвшөөрөлгүйгээр ажил олгогчтой ижил төрлийн бизнесийн үйл ажиллагаа эрхэлдэг аж ахуйн нэгж, байгууллагын үйл ажиллагаанд ямар нэгэн хэлбэрээр оролцсон, мөн өөрийн ажил үүргийн хуваарьт заасан үүргийг өөр аж ахуйн нэгж, байгууллагад давхардуулан гүйцэтгэсэн, эсхүл захиргааны чөлөөтэй болон бусад хүндэтгэн үзэх шалтгаантай байх үедээ бусад аж ахуйн нэгж, байгууллага, хувь хүнтэй ажил үүргийнхээ дагуу гэрээ, хэлцэл байгуулсан, давхар ажилласан /Ижил төрлийн үйл ажиллагаа явуулдаг байгууллагад давхар ажил гүйцэтгэсний улмаас өвчтөн-үйлчлүүлэгчид учирсан гэм хор, хохирлыг компани хариуцахгүй./;</p>
<p class="cl">5.3.12. Ажил үүрэгтээ хариуцлагагүй хандаж, хөдөлмөрийн аюулгүй байдал, эрүүл ахуйн дүрэм, журам, зааврыг зөрчсөний улмаас компанийн өмч, эд хөрөнгөд хохирол учруулсан, үйлдвэрлэлийн осол гаргахад хүргэсэн, бусдын амь нас, эд хөрөнгөд хохирол учруулсан, түүнчлэн зохих зөвшөөрөлгүйгээр компанийн эд хөрөнгийг хууль бусаар ашиглаж шамшигдуулсан, үрэгдүүлсэн, бусдад худалдсан, нуун дарагдуулсан, хулгайлсан, эсхүл хулгайн гэмт хэрэг гарах нөхцөлийг бүрдүүлсэн /хохирлын хэмжээ харгалзахгүй/;</p>
<p class="cl">5.3.13. Мэргэжлийн болон оношилгоо, эмчилгээний хэм хэмжээ, стандарт, удирдамжийг зөрчсөн, өвчтөн-үйлчлүүлэгчийн эрүүл мэндэд гэм хор, хохирол учруулсан нь тогтоогдсон /Энэ тохиолдолд эрүүл мэндийн асуудал хариуцсан төрийн эрх бүхий байгууллагад холбогдох асуудлыг шилжүүлнэ./;</p>
<p class="cl">5.3.14. Ажлын байрандаа, эсхүл олон нийтийн арга хэмжээний үеэр бусадтай зүй бусаар харьцаж зохисгүй үйлдэл гаргасан, доромжилсон, танхайрсан, эрх чөлөөнд нь халдсан, хүч хэрэглэсэн нь нотлогдсон /Энэ тохиолдолд хууль, хяналтын байгууллагад шилжүүлнэ./;</p>
<p class="cl">5.3.15. Ажил үүргээ гүйцэтгэх үедээ өөртөө болон бусдад давуу байдал үүсгэх зорилгоор ажил хаялт зохион байгуулах, оролцох, үүний улмаас компанид ямар нэг хэмжээгээр хохирол учруулсан, байгууллага, хамт олны эв нэгдлийг үймээн бутаргах зохион байгуулалттай арга хэмжээ зохион байгуулсан;</p>
<p class="cl">5.3.16. Эрүүл мэндийн тухай хууль, Эмч, эмнэлгийн ажилтны ёс зүйн хэм хэмжээ, дүрэм, журмыг зөрчсөн.</p>

<h2>Зургаа. Бусад зүйл</h2>
<p class="cl">6.1. Талууд харилцан тохиролцсоны үндсэн дээр гэрээнд зөвхөн бичгээр нэмэлт, өөрчлөлт оруулж болно. Гэрээнд нэмэлт, өөрчлөлт оруулахад талууд тэгш эрх эдэлж, оруулсан нэмэлт, өөрчлөлтийг гэрээнд хавсаргаснаар энэхүү гэрээний нэгэн адил хүчинтэй болно.</p>
<p class="cl">6.2. Энэхүү гэрээнд заагаагүй бусад харилцааг Монгол Улсын Хөдөлмөрийн тухай хуулиар зохицуулна.</p>
<p class="cl">6.3. Энэхүү гэрээ нь Талууд гарын үсэг зурсан өдрөөс эхлэн хүчин төгөлдөр болно.</p>
<p class="cl">6.4. Энэхүү гэрээг 2 хувь үйлдсэн бөгөөд Ажил олгогч, Ажилтанд тус бүр 1 хувь хадгалагдах ба хууль зүйн хувьд адил хүчинтэй байна.</p>
HTML;
    }

